//! `joyczl-protocol` — Joy's cross-language contract, the single source of truth.
//!
//! What rots first in a three-language project: "the same concept written out
//! three times" — once in Rust, hand-copied in the frontend, again in the SDK, then drift.
//!
//! This crate's approach:
//!
//!   * types are defined once, in Rust;
//!   * `#[derive(TS)]`    → `schema/typescript/` (generated by ts-rs)
//!   * `#[derive(JsonSchema)]` → `schema/json/v2.json` (generated by schemars,
//!     then handed to datamodel-code-generator to produce the Python pydantic models)
//!   * generated artifacts are **checked in**, so type drift is visible at a glance in the PR diff.
//!
//! The two generation derives become empty macros in non-test builds, so the
//! shipped binary neither depends on ts-rs/schemars nor pays derive cost. See the cfg switch below.

mod protocol;
pub mod rpc;

pub use protocol::memory_center::*;
pub use protocol::v2::*;
pub use rpc::*;

// ---- Compile-time switch for the generation derives -----------------------
// test builds: real expansion, so `cargo test` triggers code generation.
// other builds: swapped for the empty macros in joyczl-protocol-noop-macros.
#[cfg(not(test))]
pub(crate) use joyczl_protocol_noop_macros::JsonSchema;
#[cfg(not(test))]
pub(crate) use joyczl_protocol_noop_macros::TS;
#[cfg(test)]
pub(crate) use schemars::JsonSchema;
#[cfg(test)]
pub(crate) use ts_rs::TS;

#[cfg(test)]
mod export;
#[cfg(test)]
#[path = "export_tests.rs"]
mod export_tests;
